class TaskBinding {static Object animal(int kind,String name){return switch(kind){case 0->new Animal(name);case 1->new Dog(name);default->new Puppy(name);};}static String voice(Object x){Animal a=(Animal)x;return a.voice();}static String[]actions(Object x){Puppy p=(Puppy)x;return new String[]{p.run(),p.bite(),p.jump()};}static String[] dogActions(Object x){Dog d=(Dog)x;return new String[]{d.run(),d.bite()};}static String name(Object x){return ((Animal)x).name();}static boolean voiceDescribes(int kind,String name,String message){return message!=null&&message.contains(new String[]{"Animal","Dog","Puppy"}[kind])&&message.contains(name);}static boolean actionDescribes(int index,String name,String message){return message!=null&&message.contains(new String[]{"run","bite","jump"}[index])&&message.contains(name);}}
